      SUBROUTINE LIMSETCC     SET LIMITS ON PHYSICAL PARAMETERS IN FITTINGCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM39B.CIN'      INCLUDE 'ELM39C.CIN'CC-------------------------------------------------------------------      NPAR = NPARL      DPAR = DPARL      LT = 2*LTYPE - 1      IF (TYPEL .GT. 48) GO TO 1000      GO TO (  10,  20,  30,  40,  50,1000,1000,1000,1000,1000,     1       1000, 120,1000,1000,1000,1000,1000, 180, 190, 200,     2       1000,1000,1000,1000, 250,1000,1000, 280, 280,1000,     3       1000,1000,1000, 340, 350, 350,1000,1000,1000,1000,     4       1000,1000,1000,1000,1000,1000,1000,1000), TYPELC   10 ALIM1(LT) = DPAR      ALIM1(LT+1) = 1.0      GO TO 1000C   20 IF (NPAR .EQ. 1) THEN        ALIM2(LT) = DPAR*UNITI(7)        ALIM2(LT+1) = 1.0      ENDIF      GO TO 1000C   30 IF (NPAR .EQ. 1) THEN        ALIM3(LT) = DPAR*UNITI(8)        ALIM3(LT+1) = 1.0      ENDIF      GO TO 1000C   40 IF (NPAR .GE. 1 .AND. NPAR .LE. 6) THEN        IF (NPAR .EQ. 1) DPAR = DPAR*UNITI(8)        IF (NPAR .EQ. 2) DPAR = DPAR*UNITI(9)        IF (NPAR .EQ. 3) DPAR = DPAR*UNITI(8)        IF (NPAR .EQ. 4) DPAR = DPAR*UNITI(7)        IF (NPAR .EQ. 6) DPAR = DPAR/UNITI(8)**2        ALIM4(LT,NPAR) = DPAR        ALIM4(LT+1,NPAR) = 1.0      ENDIF      GO TO 1000C   50 IF (NPAR .GE. 1 .AND. NPAR .LE. 5) THEN        IF (NPAR .EQ. 1) DPAR = DPAR*UNITI(8)        IF (NPAR .EQ. 2) DPAR = DPAR*UNITI(9)        IF (NPAR .EQ. 3) DPAR = DPAR*UNITI(1)        IF (NPAR .EQ. 4) DPAR = DPAR*UNITI(9)/UNITI(1)        IF (NPAR .EQ. 5) DPAR = DPAR/UNITI(8)**2        ALIM5(LT,NPAR) = DPAR        ALIM5(LT+1,NPAR) = 1.0      ENDIF      GO TO 1000C  120 IF (NPAR .GE. 1 .AND. NPAR .LE. 15) THEN        ALIM12(LT,NPAR) = DPAR        ALIM12(LT+1,NPAR) = 1.0      ENDIF      GO TO 1000C  180 IF (NPAR .GE. 1 .AND. NPAR .LE. 4) THEN        IF (NPAR .EQ. 1) DPAR = DPAR*UNITI(8)        IF (NPAR .EQ. 2) DPAR = DPAR*UNITI(9)        IF (NPAR .EQ. 3) DPAR = DPAR*UNITI(1)        IF (NPAR .EQ. 4) DPAR = DPAR/UNITI(8)**3        ALIM18(LT,NPAR) = DPAR        ALIM18(LT+1,NPAR) = 1.0      ENDIF      GO TO 1000C  190 IF (NPAR .GE. 1 .AND. NPAR .LE. 3) THEN        IF (NPAR .EQ. 1) DPAR = DPAR*UNITI(8)        IF (NPAR .EQ. 2) DPAR = DPAR*UNITI(9)        IF (NPAR .EQ. 3) DPAR = DPAR*UNITI(12)        ALIM19(LT,NPAR) = DPAR        ALIM19(LT+1,NPAR) = 1.0      ENDIF      GO TO 1000C  200 IF (NPAR .EQ. 1) THEN        ALIM20(LT) = DPAR*UNITI(12)        ALIM20(LT+1) = 1.0      ENDIF      GO TO 1000C  250 IF (NPAR .GE. 1 .AND. NPAR .LE. 4) THEN        IF (NPAR .EQ. 1) DPAR = DPAR*UNITI(8)        IF (NPAR .EQ. 2) DPAR = DPAR*UNITI(9)        IF (NPAR .EQ. 3) DPAR = DPAR*UNITI(1)        IF (NPAR .EQ. 4) DPAR = DPAR/UNITI(8)**4        ALIM25(LT,NPAR) = DPAR        ALIM25(LT+1,NPAR) = 1.0      ENDIF      GO TO 1000C  280 IF (NPAR .GE. 1 .AND. NPAR .LE. 13) THEN        IF (NPAR .EQ. 1) DPAR = DPAR*UNITI(8)        IF (NPAR .EQ. 2) DPAR = DPAR*UNITI(9)        IF (NPAR .EQ. 3) DPAR = DPAR*UNITI(8)        IF (NPAR .EQ. 4) DPAR = DPAR*UNITI(7)        IF (NPAR .EQ. 12 .OR. NPAR .EQ. 13) DPAR = DPAR*UNITI(12)        ALIM28(LT,NPAR) = DPAR        ALIM28(LT+1,NPAR) = 1.0      ENDIF      GO TO 1000C  340 IF (NPAR .GE. 1 .AND. NPAR .LE. 5) THEN        IF (NPAR .EQ. 1) DPAR = DPAR*UNITI(8)        IF (NPAR .EQ. 2) DPAR = DPAR*UNITI(9)        IF (NPAR .EQ. 3) DPAR = DPAR*UNITI(1)        IF (NPAR .EQ. 4) DPAR = DPAR*UNITI(9)/UNITI(1)        IF (NPAR .EQ. 5) DPAR = DPAR/UNITI(8)**2        ALIM34(LT,NPAR) = DPAR        ALIM34(LT+1,NPAR) = 1.0      ENDIF      GO TO 1000C  350 IF (NPAR .GE. 1 .AND. NPAR .LE. 4) THEN        IF (NPAR .EQ. 1) DPAR = DPAR*UNITI(8)        IF (NPAR .EQ. 2) DPAR = DPAR*UNITI(9)        IF (NPAR .EQ. 3) DPAR = DPAR*UNITI(7)        IF (NPAR .EQ. 4) DPAR = DPAR*UNITI(7)        ALIM35(LT,NPAR) = DPAR        ALIM35(LT+1,NPAR) = 1.0      ENDIF      GO TO 1000C 1000 RETURN      END